CREATE OR REPLACE FUNCTION public.pamda_admin_criar_rede(p_nome text, p_codigo text, p_matriz_cliente_id uuid, p_tipo text DEFAULT 'rede'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_id uuid;v_code text;v_legacy_code text;
BEGIN
 IF NOT public.pamda_is_admin() THEN RAISE EXCEPTION 'Acesso restrito à administração' USING ERRCODE='42501'; END IF;
 v_code:=btrim(coalesce(p_codigo,''));
 IF btrim(coalesce(p_nome,''))='' OR v_code !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$' OR
   p_tipo NOT IN ('rede','franquia','grupo_comercial') THEN
  RAISE EXCEPTION 'Nome, código ou tipo da rede inválido';
 END IF;
 SELECT customer_code INTO v_legacy_code FROM public.customers
  WHERE id=p_matriz_cliente_id AND active FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Cliente principal ativo não encontrado'; END IF;
 IF EXISTS(SELECT 1 FROM public.erp_customer_network_members WHERE customer_id=p_matriz_cliente_id) THEN
  RAISE EXCEPTION 'Cliente já pertence a uma rede';
 END IF;
 INSERT INTO public.erp_customer_networks(network_name,network_code,network_kind,headquarters_customer_id,created_by)
 VALUES(btrim(p_nome),v_code,p_tipo,p_matriz_cliente_id,(SELECT auth.uid())) RETURNING id INTO v_id;
 INSERT INTO public.erp_customer_network_members(network_id,customer_id,unit_sequence,display_code,legacy_customer_code,joined_by)
 VALUES(v_id,p_matriz_cliente_id,0,v_code,v_legacy_code,(SELECT auth.uid()));
 INSERT INTO public.erp_commercial_change_audit(actor_user_id,customer_id,action,after_data,reason)
 VALUES((SELECT auth.uid()),p_matriz_cliente_id,'criar_rede_comercial',
 jsonb_build_object('network_id',v_id,'name',btrim(p_nome),'network_code',v_code),'Agrupamento comercial sem alteração dos códigos anteriores');
 RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.pamda_admin_vincular_cliente_rede(p_rede_id uuid, p_cliente_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_code text;v_legacy text;v_seq integer;v_display text;v_primary uuid;
BEGIN
 IF NOT public.pamda_is_admin() THEN RAISE EXCEPTION 'Acesso restrito à administração' USING ERRCODE='42501'; END IF;
 IF p_rede_id IS NULL OR p_cliente_id IS NULL THEN RAISE EXCEPTION 'Rede ou cliente ausente'; END IF;
 SELECT network_code,headquarters_customer_id INTO v_code,v_primary
 FROM public.erp_customer_networks WHERE id=p_rede_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Rede não encontrada'; END IF;
 SELECT customer_code INTO v_legacy FROM public.customers WHERE id=p_cliente_id AND active FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Cliente não encontrado ou inativo'; END IF;
 IF EXISTS(SELECT 1 FROM public.erp_customer_network_members WHERE customer_id=p_cliente_id) THEN
   RAISE EXCEPTION 'Este cliente já pertence a uma rede';
 END IF;
 SELECT COALESCE(MAX(unit_sequence),0)+1 INTO v_seq
 FROM public.erp_customer_network_members WHERE network_id=p_rede_id;
 v_display:=v_code||'-'||v_seq::text;
 INSERT INTO public.erp_customer_network_members(network_id,customer_id,unit_sequence,display_code,legacy_customer_code,joined_by)
 VALUES(p_rede_id,p_cliente_id,v_seq,v_display,v_legacy,(SELECT auth.uid()));
 INSERT INTO public.erp_commercial_change_audit(actor_user_id,customer_id,action,after_data,reason)
 VALUES((SELECT auth.uid()),p_cliente_id,'vincular_cliente_rede',
 jsonb_build_object('network_id',p_rede_id,'display_code',v_display,'original_code',v_legacy,'headquarters_customer_id',v_primary),
 'Vínculo de grupo sem alterar pedidos e cadastro original');
 RETURN v_display;
END;
$function$

CREATE OR REPLACE FUNCTION public.pamda_admin_configurar_cobranca_cliente(p_cliente_id uuid, p_ciclo text, p_modo text, p_dias integer, p_observacoes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_before jsonb; v_after jsonb;
BEGIN
 IF NOT public.pamda_has_permission('customers.manage') THEN RAISE EXCEPTION 'Acesso negado' USING ERRCODE='42501'; END IF;
 IF p_ciclo IS NULL OR p_ciclo NOT IN ('diario','semanal','mensal','flexivel') OR
    p_modo IS NULL OR p_modo NOT IN ('por_unidade','centralizado','flexivel') OR
    (p_dias IS NOT NULL AND (p_dias<0 OR p_dias>365)) THEN
   RAISE EXCEPTION 'Configuração de cobrança inválida';
 END IF;
 PERFORM 1 FROM public.customers WHERE id=p_cliente_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Cliente não encontrado'; END IF;
 SELECT to_jsonb(p) INTO v_before FROM public.erp_customer_billing_policies p WHERE customer_id=p_cliente_id;
 INSERT INTO public.erp_customer_billing_policies(customer_id,billing_cycle,default_collection_mode,due_days,notes,updated_by)
 VALUES(p_cliente_id,p_ciclo,p_modo,p_dias,p_observacoes,(SELECT auth.uid()))
 ON CONFLICT(customer_id) DO UPDATE SET billing_cycle=excluded.billing_cycle,
 default_collection_mode=excluded.default_collection_mode,due_days=excluded.due_days,
 notes=excluded.notes,updated_at=now(),updated_by=excluded.updated_by;
 SELECT to_jsonb(p) INTO v_after FROM public.erp_customer_billing_policies p WHERE customer_id=p_cliente_id;
 INSERT INTO public.erp_commercial_change_audit(actor_user_id,customer_id,action,before_data,after_data)
 VALUES((SELECT auth.uid()),p_cliente_id,'configurar_cobranca_cliente',v_before,v_after);
END;
$function$

CREATE OR REPLACE FUNCTION public.pamda_admin_configurar_cobranca_filial(p_filial_id uuid, p_ciclo text, p_modo text, p_dias integer, p_observacoes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_before jsonb;v_after jsonb;v_customer_id uuid;
BEGIN
 IF NOT public.pamda_has_permission('customers.manage') THEN RAISE EXCEPTION 'Acesso negado' USING ERRCODE='42501'; END IF;
 IF (p_ciclo IS NOT NULL AND p_ciclo NOT IN ('diario','semanal','mensal','flexivel')) OR
    (p_modo IS NOT NULL AND p_modo NOT IN ('por_unidade','centralizado','flexivel')) OR
    (p_dias IS NOT NULL AND (p_dias<0 OR p_dias>365)) THEN
   RAISE EXCEPTION 'Configuração de filial inválida';
 END IF;
 SELECT customer_id INTO v_customer_id FROM public.customer_branches WHERE id=p_filial_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Filial não encontrada'; END IF;
 SELECT to_jsonb(p) INTO v_before FROM public.erp_branch_billing_policies p WHERE branch_id=p_filial_id;
 INSERT INTO public.erp_branch_billing_policies(branch_id,billing_cycle,default_collection_mode,due_days,notes,updated_by)
 VALUES(p_filial_id,p_ciclo,p_modo,p_dias,p_observacoes,(SELECT auth.uid()))
 ON CONFLICT(branch_id) DO UPDATE SET billing_cycle=excluded.billing_cycle,
 default_collection_mode=excluded.default_collection_mode,due_days=excluded.due_days,
 notes=excluded.notes,updated_at=now(),updated_by=excluded.updated_by;
 SELECT to_jsonb(p) INTO v_after FROM public.erp_branch_billing_policies p WHERE branch_id=p_filial_id;
 INSERT INTO public.erp_commercial_change_audit(actor_user_id,customer_id,branch_id,action,before_data,after_data)
 VALUES((SELECT auth.uid()),v_customer_id,p_filial_id,'configurar_cobranca_filial',v_before,v_after);
END;
$function$

CREATE OR REPLACE FUNCTION public.pamda_admin_configurar_cobranca_rede(p_rede_id uuid, p_ciclo text, p_modo text, p_dias integer, p_observacoes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_before jsonb;v_after jsonb;v_head uuid;
BEGIN
 IF NOT public.pamda_is_admin() THEN RAISE EXCEPTION 'Acesso negado' USING ERRCODE='42501'; END IF;
 IF p_ciclo IS NULL OR p_ciclo NOT IN ('diario','semanal','mensal','flexivel') OR
  p_modo IS NULL OR p_modo NOT IN ('por_unidade','centralizado','flexivel') OR
  (p_dias IS NOT NULL AND (p_dias<0 OR p_dias>365)) THEN
   RAISE EXCEPTION 'Configuração de rede inválida';
 END IF;
 SELECT to_jsonb(n),headquarters_customer_id INTO v_before,v_head
 FROM public.erp_customer_networks n WHERE id=p_rede_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Rede não encontrada'; END IF;
 UPDATE public.erp_customer_networks SET default_cycle=p_ciclo,
  default_collection_mode=p_modo,default_due_days=p_dias,notes=p_observacoes,updated_at=now()
 WHERE id=p_rede_id;
 SELECT to_jsonb(n) INTO v_after FROM public.erp_customer_networks n WHERE id=p_rede_id;
 INSERT INTO public.erp_commercial_change_audit(actor_user_id,customer_id,action,before_data,after_data)
 VALUES((SELECT auth.uid()),v_head,'configurar_cobranca_rede',v_before,v_after);
END;
$function$

CREATE OR REPLACE FUNCTION public.pamda_relatorio_rede_clientes(p_rede_id uuid, p_inicio date, p_fim date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_network public.erp_customer_networks%ROWTYPE;
 v_finance boolean;
 v_start timestamptz;
 v_end timestamptz;
 v_rows jsonb;
BEGIN
 IF NOT (public.pamda_has_permission('sales.read') OR public.pamda_has_permission('customers.manage')) THEN
  RAISE EXCEPTION 'Acesso negado' USING ERRCODE='42501';
 END IF;
 IF p_rede_id IS NULL OR p_inicio IS NULL OR p_fim IS NULL OR
   p_fim<p_inicio OR p_fim>p_inicio+interval '5 years' THEN
   RAISE EXCEPTION 'Rede ou período inválido';
 END IF;
 SELECT * INTO v_network FROM public.erp_customer_networks WHERE id=p_rede_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Rede não encontrada'; END IF;
 v_finance:=public.pamda_has_permission('finance.read');
 v_start:=p_inicio::timestamp AT TIME ZONE 'America/Sao_Paulo';
 v_end:=(p_fim+1)::timestamp AT TIME ZONE 'America/Sao_Paulo';
 SELECT coalesce(jsonb_agg(jsonb_build_object(
  'customer_id',c.id,'customer_name',c.name,'legacy_customer_code',m.legacy_customer_code,
  'group_display_code',m.display_code,'branch_id',b.id,'branch_name',b.name,
  'primary_branch',b.is_primary,'unit_sequence',m.unit_sequence,
  'billing_cycle',coalesce(bp.billing_cycle,cp.billing_cycle,v_network.default_cycle),
  'collection_mode',coalesce(bp.default_collection_mode,cp.default_collection_mode,v_network.default_collection_mode),
  'due_days',coalesce(bp.due_days,cp.due_days,v_network.default_due_days),
  'orders_started',tot.orders_started,
  'orders_confirmed_real',tot.real_confirmed,
  'orders_confirmed_test',tot.test_confirmed,
  'orders_cancelled',tot.cancelled,
  'purchases_real',CASE WHEN v_finance THEN tot.real_value ELSE null END,
  'purchases_test',CASE WHEN v_finance THEN tot.test_value ELSE null END,
  'paid_real',null,'paid_test',null,'payments_integrated',false
 ) ORDER BY m.unit_sequence,c.customer_code,b.name),'[]'::jsonb) INTO v_rows
 FROM public.erp_customer_network_members m
 JOIN public.customers c ON c.id=m.customer_id
 JOIN public.customer_branches b ON b.customer_id=c.id
 LEFT JOIN public.erp_customer_billing_policies cp ON cp.customer_id=c.id
 LEFT JOIN public.erp_branch_billing_policies bp ON bp.branch_id=b.id
 CROSS JOIN LATERAL (
  SELECT count(*) AS orders_started,
  count(*) FILTER (WHERE s.status='confirmed' AND NOT s.is_test) AS real_confirmed,
  count(*) FILTER (WHERE s.status='confirmed' AND s.is_test) AS test_confirmed,
  count(*) FILTER (WHERE s.status='cancelled') AS cancelled,
  coalesce(sum(s.total) FILTER (WHERE s.status='confirmed' AND NOT s.is_test),0) AS real_value,
  coalesce(sum(s.total) FILTER (WHERE s.status='confirmed' AND s.is_test),0) AS test_value
  FROM public.erp_sales s
  WHERE s.customer_id=c.id AND s.branch_id=b.id
    AND s.created_at>=v_start AND s.created_at<v_end
 ) tot
 WHERE m.network_id=p_rede_id;
 RETURN jsonb_build_object('network_id',v_network.id,'network_name',v_network.network_name,
   'network_code',v_network.network_code,'network_kind',v_network.network_kind,
   'from',p_inicio,'to',p_fim,'payments_integrated',false,
   'financial_authorized',v_finance,'units',v_rows);
END;
$function$
